"use strict";(self.webpackChunkpython_bridge_docs=self.webpackChunkpython_bridge_docs||[]).push([[166],{2310:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"willkommen","metadata":{"permalink":"/python-bridge/blog/willkommen","source":"@site/blog/2026-09-06-willkommen.md","title":"Willkommen bei Python Bridge","description":"Python Bridge verbindet Godot 4 mit Python \u2014 ohne Python in eine eigene","date":"2026-09-06T00:00:00.000Z","tags":[{"inline":true,"label":"release","permalink":"/python-bridge/blog/tags/release"},{"inline":true,"label":"godot","permalink":"/python-bridge/blog/tags/godot"},{"inline":true,"label":"python","permalink":"/python-bridge/blog/tags/python"}],"readingTime":0.795,"hasTruncateMarker":true,"authors":[{"name":"Python Bridge Team","role":"Maintainer","url":"https://github.com/CyberToshi/python-bridge","key":"python-bridge-team","page":null}],"frontMatter":{"slug":"willkommen","title":"Willkommen bei Python Bridge","authors":["python-bridge-team"],"tags":["release","godot","python"],"date":"2026-09-06T00:00:00.000Z"},"unlisted":false},"content":"**Python Bridge** verbindet Godot 4 mit Python \u2014 ohne Python in eine eigene\\nSprache zu verwandeln. Du schreibst weiterhin normale `.py`-Dateien, und\\nGDScript bleibt deine einfache Godot-Schnittstelle.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Was die Bridge heute schon kann\\n\\n- Python-Prozesse starten, \xfcberwachen und sauber beenden\\n- asynchrone Tasks mit Priorit\xe4ten, Batching und Backpressure\\n- strukturierte Fehler inklusive Python-Traceback in Godot\\n- mehrere Python-Instanzen und Worker-Slots parallel\\n- automatische projektbezogene `venv` mit Dependency-Verwaltung\\n- Hot Reload von Python-Code aus dem Godot-Editor\\n- DataRefs und Datei-Transport f\xfcr gro\xdfe numerische Ergebnisse\\n- Crash-Restart mit exponentiellem Backoff und Health Monitoring\\n\\n## Der aktuelle Stand\\n\\nDie Python-Runtime ist durch eine umfassende Testsuite abgedeckt\\n(90 Tests gr\xfcn). Die Godot-Integration folgt der Verifikations-Checkliste\\nin der [Dokumentation](/docs/godot-verification).\\n\\n## Was als N\xe4chstes kommt\\n\\n1. End-to-End-Verifikation der Godot-Integration im Editor (P0)\\n2. Verifikation des Shared-Memory-Datenpfads aus Godot heraus\\n3. Automatisierte Builds f\xfcr den GDExtension-Hochleistungspfad\\n\\nDer einfachste Einstieg ist das\\n[Hello-World-Beispiel](/docs/getting-started) \u2014 Godot startet Python dabei\\nselbst, du brauchst kein Terminal."}]}}')}}]);